SELECT a.seq , a.ch_tp , a.cont_nm , a.cont_grp_cd , a.use_yn , a.del_yn , a.reg_dt , ifnull(a.upd_dt, a.reg_dt) as upd_dt , a.cont_tp_lst , a.cont_tp_lst_nm , b.cont_tp , c.cd_nm AS cont_tp_nm , b.CONT_SUB , b.CONT_TOP_BODY , b.CONT_BODY , b.send_tp , d.cd_nm AS send_tp_nm , g.list_val as send_to , g.list_nm AS send_nm , b.thm_url , b.br_yn , b.sup_yn , b.msg_tp , f.cd_nm as msg_tp_nm , b.kko_img_cd , e.IMG_URL AS kko_image_url , b.kko_img_url , b.kko_BTN_nm , b.KKO_BTN_URL , CONCAT_WS(',', img_1.IMG_URL, img_2.IMG_URL, img_3.IMG_URL, img_4.IMG_URL, img_5.IMG_URL, img_6.IMG_URL) AS IMG_LST , b.RCS_BTN_INS_TP , b.RCS_BTN_CNT , b.RCS_BTN_OBJ , b.RCS_BTN_1 , b.RCS_BTN_TP_1 , b.RCS_BTN_CONT_1 , b.RCS_BTN_2 , b.RCS_BTN_TP_2 , b.RCS_BTN_CONT_2 , b.RCS_BTN_3 , b.RCS_BTN_TP_3 , b.RCS_BTN_CONT_3 , b.RCS_FOOTER FROM ( SELECT mst.seq AS seq , mst.ch_tp AS ch_tp , mst.cont_nm AS cont_nm , mst.cont_grp_cd AS cont_grp_cd , mst.use_yn AS use_yn , mst.del_yn AS del_yn , mst.reg_dt AS reg_dt , mst.upd_dt AS upd_dt , GROUP_CONCAT(lst.SEQ) AS lst_SEQS , Group_concat(lst.cont_tp) AS cont_tp_lst , Group_concat(cd_cont.cd_nm) AS cont_tp_lst_nm , CASE WHEN FIND_IN_SET('DMTP04', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP04', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP03', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP03', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP02', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP02', Group_concat(lst.cont_tp))), ',', -1) ELSE lst.SEQ END AS lst_seq FROM tblmi_cont_mst AS mst LEFT JOIN tblmi_cont_lst AS lst ON lst.cont_cd = mst.seq AND lst.USE_YN = 'Y' INNER JOIN tblmi_comm_cd AS cd_cont ON lst.cont_tp = cd_cont.cd_id
and mst.seq = #{seq}
and mst.del_yn = #{del_yn}
and mst.use_yn = #{use_yn}
and mst.cont_grp_cd = #{cont_grp_cd}
and mst.ch_tp = #{ch_tp}
and mst.CONT_NM like concat('%', #{cont_nm}, '%')
and mst.REG_DT = #{reg_dt}
and (mst.REG_DT >= #{reg_dt} and mst.REG_DT < #{reg_dt_range})
and mst.REG_DT = #{reg_dt}
GROUP BY mst.seq ORDER BY mst.reg_dt DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}
) AS a INNER JOIN tblmi_cont_lst AS b ON a.lst_seq = b.SEQ INNER JOIN tblmi_comm_cd AS c ON b.cont_tp = c.cd_id INNER JOIN tblmi_comm_cd AS d ON b.send_tp = d.cd_id INNER JOIN tblmi_comm_cd AS f ON b.msg_tp = f.cd_id INNER JOIN tblmi_set_lst AS g ON b.SEND_TO = g.SEQ LEFT JOIN tblmi_cont_img AS e ON b.kko_img_cd = e.seq LEFT JOIN tblmi_cont_img AS img_1 ON b.IMG_CD_1 = img_1.seq LEFT JOIN tblmi_cont_img AS img_2 ON b.IMG_CD_2 = img_2.seq LEFT JOIN tblmi_cont_img AS img_3 ON b.IMG_CD_3 = img_3.seq LEFT JOIN tblmi_cont_img AS img_4 ON b.IMG_CD_4 = img_4.seq LEFT JOIN tblmi_cont_img AS img_5 ON b.IMG_CD_5 = img_5.seq LEFT JOIN tblmi_cont_img AS img_6 ON b.IMG_CD_6 = img_6.seq

SELECT a.seq , a.ch_tp , a.cont_nm , a.cont_grp_cd , a.reg_dt , ifnull(a.upd_dt, a.reg_dt) as upd_dt , a.cont_tp_lst , a.cont_tp_lst_nm , b.cont_tp , c.cd_nm AS cont_tp_nm , b.CONT_SUB , b.CONT_TOP_BODY , b.CONT_BODY , b.send_tp , d.cd_nm AS send_tp_nm , b.send_to , b.send_nm , b.thm_url , b.br_yn , b.sup_yn , b.msg_tp , f.cd_nm as msg_tp_nm , b.kko_img_cd , e.IMG_URL AS kko_image_url , b.kko_img_url , b.kko_BTN_nm , b.KKO_BTN_URL , CONCAT_WS(',', img_1.IMG_URL, img_2.IMG_URL, img_3.IMG_URL, img_4.IMG_URL, img_5.IMG_URL, img_6.IMG_URL) AS IMG_LST , b.RCS_BTN_INS_TP , b.RCS_BTN_CNT , b.RCS_BTN_OBJ , b.RCS_BTN_1 , b.RCS_BTN_TP_1 , b.RCS_BTN_CONT_1 , b.RCS_BTN_2 , b.RCS_BTN_TP_2 , b.RCS_BTN_CONT_2 , b.RCS_BTN_3 , b.RCS_BTN_TP_3 , b.RCS_BTN_CONT_3 , b.RCS_FOOTER FROM ( SELECT mst.seq AS seq , mst.ch_tp AS ch_tp , mst.cont_nm AS cont_nm , mst.cont_grp_cd AS cont_grp_cd , mst.reg_dt AS reg_dt , mst.upd_dt AS upd_dt , GROUP_CONCAT(lst.SEQ) AS lst_SEQS , Group_concat(lst.cont_tp) AS cont_tp_lst , Group_concat(cd_cont.cd_nm) AS cont_tp_lst_nm , CASE WHEN FIND_IN_SET('DMTP04', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP04', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP03', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP03', Group_concat(lst.cont_tp))), ',', -1) WHEN FIND_IN_SET('DMTP02', Group_concat(lst.cont_tp)) != 0 then SUBSTRING_INDEX(SUBSTRING_INDEX(GROUP_CONCAT(lst.SEQ), ',', FIND_IN_SET('DMTP02', Group_concat(lst.cont_tp))), ',', -1) ELSE lst.SEQ END AS lst_seq FROM tblmicp_cont_mst AS mst LEFT JOIN tblmicp_cont_lst AS lst ON lst.cont_cd = mst.seq INNER JOIN tblmi_comm_cd AS cd_cont ON lst.cont_tp = cd_cont.cd_id
and mst.seq = #{seq}
and mst.cont_grp_cd = #{cont_grp_cd}
and mst.ch_tp = #{ch_tp}
and mst.CONT_NM like concat('%', #{cont_nm}, '%')
and mst.REG_DT = #{reg_dt}
and (mst.REG_DT >= #{reg_dt} and mst.REG_DT < #{reg_dt_range})
and mst.REG_DT = #{reg_dt}
GROUP BY mst.seq ORDER BY mst.reg_dt DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}
) AS a INNER JOIN tblmicp_cont_lst AS b ON a.lst_seq = b.SEQ INNER JOIN tblmi_comm_cd AS c ON b.cont_tp = c.cd_id INNER JOIN tblmi_comm_cd AS d ON b.send_tp = d.cd_id INNER JOIN tblmi_comm_cd AS f ON b.msg_tp = f.cd_id LEFT JOIN tblmi_cont_img AS e ON b.kko_img_cd = e.seq LEFT JOIN tblmi_cont_img AS img_1 ON b.IMG_CD_1 = img_1.seq LEFT JOIN tblmi_cont_img AS img_2 ON b.IMG_CD_2 = img_2.seq LEFT JOIN tblmi_cont_img AS img_3 ON b.IMG_CD_3 = img_3.seq LEFT JOIN tblmi_cont_img AS img_4 ON b.IMG_CD_4 = img_4.seq LEFT JOIN tblmi_cont_img AS img_5 ON b.IMG_CD_5 = img_5.seq LEFT JOIN tblmi_cont_img AS img_6 ON b.IMG_CD_6 = img_6.seq

