select a.SEQ as SEND_HST_SEQ , a.PRO_ID , a.SEND_TO , a.SEND_NM , ifnull(b.SEQ, "") as SEQ , ifnull(b.USR_ID, "") as USR_ID , ifnull(b.USR_NM, "") as USR_NM , ifnull(b.USR_MOB, "") as USR_MOB , ifnull(b.USR_EDM, "") as USR_EDM , ifnull(b.USR_GDR, "") as USR_GDR , ifnull(b.USR_ADDR, "") as USR_ADDR , ifnull(b.USR_ETC1, "") as USR_ETC1 , ifnull(b.USR_ETC2, "") as USR_ETC2 , ifnull(b.USR_ETC3, "") as USR_ETC3 , ifnull(b.USR_ETC4, "") as USR_ETC4 , ifnull(b.USR_ETC5, "") as USR_ETC5 , ifnull(b.USR_ETC6, "") as USR_ETC6 , ifnull(b.USR_ETC7, "") as USR_ETC7 , ifnull(b.USR_ETC8, "") as USR_ETC8 , ifnull(b.USR_ETC9, "") as USR_ETC9 , ifnull(b.USR_ETC10, "") as USR_ETC10 from tblmicp_send_hst as a left join ${tbl_id} as b on a.TBL_LST_ID = b.seq
and a.pro_id = #{pro_id}
