SELECT camp.* , comm.cd_desc AS team_nm
,cont.avo_nm as avo_nm
FROM tblmicp_campaign AS camp
	LEFT JOIN tblmicp_cont_mst AS cont ON cont.seq = camp.CONT_ID
	LEFT JOIN tblmi_comm_cd AS comm
		ON comm.grp_id = 'GRP_TEAM'
		    AND cd_id = 'TEAM01'
			AND cont.team_cd = comm.cd_val
			AND camp.usr_grp_cd = comm.par_id


		and camp.seq = #{seq}


		and camp.pro_id = #{pro_id}


		and camp.cont_id = #{cont_id}


		and camp.usr_grp_cd = #{usr_grp_cd}


		and camp.start_dt  >= #{start_dt} 


		and camp.start_dt  <#{end_dt}

select a.* , CONCAT_WS(',', img_1.IMG_URL, img_2.IMG_URL, img_3.IMG_URL, img_4.IMG_URL, img_5.IMG_URL, img_6.IMG_URL) AS IMG_LST , CONCAT_WS(',', img_1.IMG_FILE_NM, img_2.IMG_FILE_NM, img_3.IMG_FILE_NM, img_4.IMG_FILE_NM, img_5.IMG_FILE_NM, img_6.IMG_FILE_NM) AS IMG_NM_LST , e.CH_TP AS ch_tp , e.IMG_URL as kko_image_url , e.IMG_FILE_NM as kko_image_file_nm , e.KKO_IMG_URL as kko_server_image_url , d.cd_nm AS send_tp_nm , f.cd_val as msg_tp_val from tblmicp_cont_lst as a INNER JOIN tblmi_comm_cd AS d ON a.send_tp = d.cd_id LEFT JOIN tblmi_cont_img AS e ON a.kko_img_cd = e.seq INNER JOIN tblmi_comm_cd AS f ON a.msg_tp = f.cd_id LEFT JOIN tblmi_cont_img AS img_1 ON a.IMG_CD_1 = img_1.seq LEFT JOIN tblmi_cont_img AS img_2 ON a.IMG_CD_2 = img_2.seq LEFT JOIN tblmi_cont_img AS img_3 ON a.IMG_CD_3 = img_3.seq LEFT JOIN tblmi_cont_img AS img_4 ON a.IMG_CD_4 = img_4.seq LEFT JOIN tblmi_cont_img AS img_5 ON a.IMG_CD_5 = img_5.seq LEFT JOIN tblmi_cont_img AS img_6 ON a.IMG_CD_6 = img_6.seq
and a.seq = #{seq}
and a.cont_tp = #{cont_tp}
and a.cont_cd = #{cont_cd}
and a.CONT_GRP_CD = #{cont_grp_cd}

