SELECT camp_id , COUNT(*) AS t_cnt , count(if(send_rst is NULL, 1, null)) as w_cnt , count(if(send_rst = '0', 1, null)) as s_cnt , count(if(send_rst = '1', 1, null)) as f_cnt FROM tblmicp_send_hst
pro_id = #{pro_id}
GROUP BY camp_id

SELECT camp_id , COUNT(*) AS cnt FROM tblmicp_track_open
pro_id = #{pro_id}
GROUP BY camp_id

SELECT camp_id , COUNT(*) AS cnt FROM ( SELECT camp_id , msg_tp FROM tblmicp_track_url
pro_id = #{pro_id}
GROUP BY pro_id, camp_id, tbl_id, tbl_lst_id ) AS z GROUP BY camp_id

SELECT COUNT(*) AS cnt -- 토탈 , count(if(PRO_ST = '00', 1, NULL)) AS aw_cnt -- 승인 대기 , count(if(PRO_ST = '01', 1, NULL)) AS wait_cnt -- 발송 대기 , count(if(PRO_ST = '02', 1, NULL)) AS tar_cnt -- 타겟 추출 , count(if(PRO_ST = '03', 1, NULL)) AS send_cnt -- 발송 , count(if(PRO_ST = '04', 1, NULL)) AS suc_cnt -- 발송 , count(if(PRO_ST = '98', 1, NULL)) AS temp_cnt -- 임시저장 , count(if(PRO_ST = '99', 1, NULL)) AS err_cnt -- 에러 FROM tblmicp_program as prg LEFT JOIN tblmi_comm_cd AS proStCd ON (proStCd.cd_id = prg.pro_st and proStCd.grp_id = 'COMST')
prg.DEL_YN = 'N'
AND prg.usr_grp_cd = #{usr_grp_cd}
and prg.pro_tp = #{pro_tp}
and prg.appr_id = #{appr_id}
and prg.reg_id= #{reg_id}

SELECT b.camp_nm , a.send_to , a.send_nm , a.send_rep_time , a.send_log_time , case WHEN a.send_rst IS NULL THEN if(b.START_DT > NOW(), '발송대기', '결과대기') when a.send_rst = '0' then '발송성공' ELSE '발송실패' END AS send_rst , a.send_rst_det , c.cd_desc , a.send_mdm FROM tblmicp_send_hst AS a INNER JOIN tblmicp_campaign AS b ON a.camp_id = b.seq LEFT JOIN tblmi_comm_cd AS c ON c.grp_id = 'SENDRESULT' AND a.send_rst_det = c.CD_ID and a.M_SERVER = c.cd_nm AND a.send_rst_tp = c.par_id
a.pro_id = #{pro_id} and a.usr_grp_cd = #{usr_grp_cd}
and a.send_rst = #{send_rst}
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

mapper.insert:
insert into tblmicp_program
(
	pro_id, pro_tp, pro_st, pro_nm, pro_tg_tp, pro_tg_id, grp_cnt, camp_cnt, cont_cnt, tar_cnt, resp_cnt, usr_grp_cd, reg_id, appr_id
	, plan_cost, off_cost, dev_cost, des_cost, inten_id, orig_id, inta_key, inta_ve
)
values
(
	#{pro_id}, #{pro_tp}, #{pro_st}, #{pro_nm}, #{pro_tg_tp}, #{pro_tg_id}, #{grp_cnt}, #{camp_cnt}, #{cont_cnt}, #{tar_cnt}, #{resp_cnt}, #{usr_grp_cd}, #{reg_id}, #{appr_id}
	, #{plan_cost}, #{off_cost}, #{dev_cost}, #{des_cost}, #{inten_id}, #{orig_id}, #{inta_key}, #{inta_ve}
)
ON DUPLICATE KEY UPDATE
	pro_id = #{pro_id}
	, pro_tp = #{pro_tp}
	, pro_st = #{pro_st}
	, pro_nm = #{pro_nm}
	, pro_tg_tp = #{pro_tg_tp}
	, pro_tg_id = #{pro_tg_id}
	, grp_cnt = #{grp_cnt}
	, camp_cnt = #{camp_cnt}
	, cont_cnt = #{cont_cnt}
	, tar_cnt = #{tar_cnt}
	, resp_cnt = #{resp_cnt}
	, usr_grp_cd = #{usr_grp_cd}
	, appr_id = #{appr_id}
	, plan_cost = #{plan_cost}
	, off_cost = #{off_cost}
	, dev_cost = #{dev_cost}
	, des_cost = #{des_cost}
	, upd_id = #{reg_id}

	insert into tblmicp_send_hst (
    	pro_id, camp_id, cont_id, tbl_id, tbl_lst_id, usr_key, send_to, send_nm, send_yn, auto_tp, usr_grp_cd, reg_id, camp_ch
    )
	values (
		#{pro_id}, #{camp_id}, #{cont_id}, #{tbl_id}, #{tbl_lst_id}, #{usr_key}, #{send_to}, #{send_nm}, #{send_yn}, #{auto_tp}, #{usr_grp_cd}, #{reg_id}, #{camp_ch}
	)

insert into Tblmicp_campaign (
	 pro_id, cont_id, send_tg_tp, send_tg_id, camp_st, camp_nm, camp_ch, test_tp, test_sampling, cont_cnt, test_cnt, real_cnt, usr_grp_cd, reg_id, sto, tar_cnt
	, start_dt
	, send_st_tp
	, end_dt
	, suppressed
	, duplicate
	, test_dt
	, ab_gb
	, ab_st
	, seq
)
values (
	#{pro_id}, #{cont_id}, #{send_tg_tp}, #{send_tg_id}, #{camp_st}, #{camp_nm}, #{camp_ch}, #{test_tp}, #{test_sampling}, #{cont_cnt}, #{test_cnt}, #{real_cnt}, #{usr_grp_cd}, #{reg_id}, #{sto}, #{tar_cnt}
	, #{start_dt}
	, #{send_st_tp}
	, #{end_dt}
	, #{suppressed}
	, #{duplicate}
	, #{test_dt}
	, #{ab_gb}
	, #{ab_st}
	, #{seq}
)
ON DUPLICATE KEY UPDATE
	pro_id = #{pro_id}
	, cont_id = #{cont_id}
	, send_tg_tp = #{send_tg_tp}
	, send_tg_id = #{send_tg_id}
	, camp_st = #{camp_st}
	, camp_nm = #{camp_nm}
	, camp_ch = #{camp_ch}
	, test_tp = #{test_tp}
	, test_sampling = #{test_sampling}
	, cont_cnt = #{cont_cnt}
	, test_cnt = #{test_cnt}
	, real_cnt = #{real_cnt}
	, usr_grp_cd = #{usr_grp_cd}
	, upd_id = #{reg_id}
	, sto = #{sto}
	, start_dt = #{start_dt}
	, send_st_tp = #{send_st_tp}
	, end_dt = #{end_dt}
	, suppressed = #{suppressed}
	, duplicate = #{duplicate}
	, test_dt = #{test_dt}
	, ab_gb = #{ab_gb}
	, ab_st = #{ab_st}

mapper.update:
update tblmicp_program

		upd_id = #{upd_id}
		, tar_cnt = #{tar_cnt}
		, resp_cnt = #{resp_cnt}
		, pro_st = #{pro_st}
		, min_start_dt = #{min_start_dt}
		, max_start_dt = #{max_start_dt}


	pro_id = #{pro_id}

update tblmicp_campaign set
	tar_cnt = (SELECT COUNT(*) FROM tblmicp_send_hst WHERE PRO_ID = #{pro_id} and CAMP_ID = #{seq})

	seq = #{seq}

update tblmicp_program set
	tar_cnt = (
		SELECT ifnull(SUM(tar_cnt), 0) AS cnt
		FROM tblmicp_campaign
		WHERE pro_id = #{pro_id}
		GROUP BY pro_id
	)

	pro_id = #{pro_id}

mapper.select:
SELECT prg.pro_id , comm_co.cd_nm as pro_st_nm , prg.pro_st , prg.pro_tp as pro_tp , prg.pro_tg_tp , prg.PRO_nm , prg.min_start_dt as start_dt , Max(hst.LAST_SEND_DT) as last_send_dt , prg.tar_cnt , prg.send_cnt , prg.reg_id , prg.pro_tg_tp , comm_tg.cd_nm AS pro_tg_tp_nm , prg.pro_tg_id FROM tblmicp_program AS prg LEFT JOIN tblmire_send_hst AS hst ON prg.pro_id = hst.pro_id INNER JOIN tblmi_comm_cd AS comm_co ON comm_co.grp_id = 'COMST' and prg.PRO_ST = comm_co.CD_ID INNER JOIN tblmi_comm_cd AS comm_tg ON comm_tg.grp_id = 'TGTP' and prg.PRO_TG_TP = comm_tg.cd_id
prg.usr_grp_cd = #{usr_grp_cd} and prg.del_yn = 'N'
and prg.pro_nm like CONCAT('%', #{pro_nm},'%')
and comm_co.cd_nm like CONCAT('%', #{cd_nm},'%')
and prg.pro_tg_tp = #{pro_tg_tp}
and prg.pro_tp = #{pro_tp}
and prg.pro_st = #{pro_st}
and prg.min_start_dt >= #{st_dt}
and prg.min_start_dt <= date_add(#{end_dt}, interval 1 day)
group by prg.pro_id order by FIELD(prg.pro_st, '98') DESC , prg.min_start_dt desc
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

select count(*)
from (
SELECT  a.pro_id
FROM tblmicp_program AS a
INNER JOIN tblmi_comm_cd AS b ON b.grp_id = 'COMST' and a.PRO_ST = b.CD_ID
INNER JOIN tblmi_comm_cd AS e ON e.grp_id = 'TGTP' and a.PRO_TG_TP = e.cd_id

	a.usr_grp_cd = #{usr_grp_cd}
	and a.del_yn = 'N'

		and a.pro_nm like CONCAT('%',  #{pro_nm},'%')


		and b.cd_nm like CONCAT('%',  #{cd_nm},'%')


		and a.pro_tg_tp = #{pro_tg_tp}


		and a.pro_tp = #{pro_tp}


		and a.pro_st = #{pro_st}


		and a.min_start_dt  >= #{st_dt} 


		and a.min_start_dt  <= date_add(#{end_dt}, interval 1 day)  



group by pro_id
) as z

SELECT COUNT(*) AS cnt -- 토탈 , count(if(PRO_ST = '00', 1, NULL)) AS aw_cnt -- 승인 대기 , count(if(PRO_ST = '01', 1, NULL)) AS wait_cnt -- 발송 대기 , count(if(PRO_ST = '02', 1, NULL)) AS tar_cnt -- 타겟 추출 , count(if(PRO_ST = '03', 1, NULL)) AS send_cnt -- 발송 , count(if(PRO_ST = '04', 1, NULL)) AS suc_cnt -- 발송 , count(if(PRO_ST = '98', 1, NULL)) AS temp_cnt -- 임시저장 , count(if(PRO_ST = '99', 1, NULL)) AS err_cnt -- 에러 FROM tblmicp_program as prg LEFT JOIN tblmi_comm_cd AS proStCd ON (proStCd.cd_id = prg.pro_st and proStCd.grp_id = 'COMST') LEFT JOIN tblmi_comm_cd AS proTpCd ON (proTpCd.cd_id = prg.pro_tp and proTpCd.grp_id = 'PROTP') LEFT JOIN tblmi_comm_cd AS tpTpCd ON (tpTpCd.cd_id = prg.pro_tg_tp and tpTpCd.grp_id = 'TGTP') LEFT JOIN tblmi_usr AS usr ON usr.usr_id = prg.reg_id LEFT JOIN tblmicp_campaign AS camp ON camp.pro_id = prg.pro_id
/*INNER JOIN tblmi_tbl_mst as mst ON mst.seq = camp.send_tg_id*/
LEFT JOIN tblmi_target_grp as tar ON tar.seq = prg.pro_tg_id
/*INNER JOIN tblmite_target_grp as tar ON tar.seq = prg.pro_tg_id*/
where prg.USR_GRP_CD = #{usr_grp_cd} and prg.del_yn = 'N'
and prg.pro_id like CONCAT('%', #{pro_id},'%')
and prg.pro_nm like CONCAT('%', #{pro_nm},'%')
and prg.pro_tp = #{pro_tp}
and camp.start_dt >= #{st_dt}
and camp.start_dt <= date_add(#{end_dt}, interval 1 day)
and (usr.usr_nm like CONCAT('%', #{usr_nm},'%') or usr.usr_log_id like CONCAT('%', #{usr_nm},'%'))
and prg.pro_tg_tp = #{pro_tg_tp}
and tar.grp_nm like CONCAT('%', #{target_nm},'%')
